LOCALES["fa"] = json.loads((ROOT / "locales" / "fa.json").read_text(encoding="utf-8"))


def render_language_nav(slug: str, page: str, label: str) -> str:
    locales = (("en", "English", ""), ("ja", "日本語", "ja"), ("zh-CN", "简体中文", "zh-cn"), ("es", "Español", "es"), ("fa", "فارسی", "fa"))
    links = []
    for lang, title, path in locales:
        href = (f"/{path}/" if page == "index" else f"/{path}/docs.html") if path else ("/" if page == "index" else "/docs.html")
        current = ' aria-current="page"' if lang == (LOCALES[slug]["lang"] if slug != "en" else "en") else ""
        links.append(f'<a href="{href}" lang="{lang}"{current}>{title}</a>')
    return f'<div class="language-nav" role="group" aria-label="{html.escape(label, quote=True)}">{"".join(links)}</div>'


def localize_html(source: str, slug: str, config: dict, page: str) -> str:
    strings = config["strings"]
    protected: list[str] = []
    for original, translated in config["code_samples"].items():
        source = source.replace(original, translated)
        if config.get("direction") == "rtl":
            source = source.replace(f"<code>{translated}</code>", f'<code lang="{config["lang"]}" dir="rtl">{translated}</code>')

    def protect(match: re.Match) -> str:
        protected.append(match.group(0))
        return f"__FLOCK_PROTECTED_{len(protected) - 1}__"

    source = re.sub(r"<script\b[^>]*>.*?</script\s*>", protect, source, flags=re.I | re.S)

    def protect_code(match: re.Match) -> str:
        protected.append(match.group(2))
        return match.group(1) + f"__FLOCK_PROTECTED_{len(protected) - 1}__" + match.group(3)

    source = re.sub(r"(<code\b[^>]*>)(.*?)(</code\s*>)", protect_code, source, flags=re.I | re.S)

    missing: set[str] = set()

    def translate_node(match: re.Match) -> str:
        raw = match.group(1)
        if raw.strip().startswith("__FLOCK_PROTECTED_"):
            return match.group(0)
        decoded = html.unescape(raw)
        key = decoded.strip()
        if not key:
            return match.group(0)
        if key not in strings:
            missing.add(key)
            return match.group(0)
        leading = decoded[: len(decoded) - len(decoded.lstrip())]
        trailing = decoded[len(decoded.rstrip()) :]
        translated = leading + strings[key] + trailing
        return ">" + html.escape(translated, quote=False) + "<"

    source = re.sub(r">([^<>]+)<", translate_node, source)
    missing -= EXPECTED_SHARED_TEXT
    if missing:
        print(f"Untranslated visible text in {slug}/{page}:" + "\n  - " + "\n  - ".join(sorted(missing)))

    for token in reversed(range(len(protected))):
        source = source.replace(f"__FLOCK_PROTECTED_{token}__", protected[token])

    if slug == "fa":
        source = source.replace("بخواه از مهارت <code>flock</code> را اجرا کند.", "بخواه مهارت <code>flock</code> را اجرا کند.")
        source = source.replace("بعد مهارت <code>/flock:flock</code>", "بعد این مهارت را اجرا کن: <code>/flock:flock</code>")

    if slug != "en":
        def remove_website_schema(match: re.Match) -> str:
            try:
                schema = json.loads(match.group(2))
            except json.JSONDecodeError:
                return match.group(0)
            return "" if schema.get("@type") == "WebSite" else match.group(0)

        source = re.sub(r'(<script type="application/ld\+json">\s*)(.*?)(\s*</script>)', remove_website_schema, source, flags=re.S)

    direction = f' dir="{config["direction"]}"' if config.get("direction") == "rtl" else ""
    source = source.replace('<html lang="en">', f'<html lang="{config["lang"]}"{direction}>')
    source = re.sub(r'(<a class="brand(?: footer-brand)?" href=")/"', rf'\1/{slug}/"', source)
    source = source.replace('href="/#workflow"', f'href="/{slug}/#workflow"')
    source = source.replace('href="/#hosts"', f'href="/{slug}/#hosts"')
    for original, translated in config["aria"].items():
        source = source.replace(f'aria-label="{original}"', f'aria-label="{html.escape(translated, quote=True)}"')

    metas = config["meta_home" if page == "index" else "meta_docs"]
    for name, value in metas.items():
        if name == "description":
            source = re.sub(r'(<meta name="description" content=")[^"]*(">)', lambda m: m.group(1) + html.escape(value, quote=True) + m.group(2), source, count=1)
        else:
            prop = re.escape(name)
            source = re.sub(rf'(<meta property="{prop}" content=")[^"]*(">)|(<meta name="{prop}" content=")[^"]*(">)', lambda m: (m.group(1) or m.group(3)) + html.escape(value, quote=True) + (m.group(2) or m.group(4)), source, count=1)

    locale_url = f"{BASE_URL}/{slug}/" if page == "index" else f"{BASE_URL}/{slug}/docs.html"
    canonical = f"{BASE_URL}/" if page == "index" and slug == "en" else f"{BASE_URL}/docs.html" if page == "docs" and slug == "en" else locale_url
    source = re.sub(r'(<link rel="canonical" href=")[^"]*(">)', lambda m: m.group(1) + canonical + m.group(2), source, count=1)
    source = re.sub(r'(<meta property="og:url" content=")[^"]*(">)', lambda m: m.group(1) + canonical + m.group(2), source, count=1)
    source = source.replace('content="en_US"', f'content="{config["og"]}"', 1)
    stylesheet = "../assets/site.css" if slug != "en" else "assets/site.css"
    script_url = "../assets/site.js" if slug != "en" else "assets/site.js"
    icon_url = "../favicon.svg" if slug != "en" else "favicon.svg"
    source = re.sub(r'href="(?:\.\./)?assets/site\.css\?v=[^"]+"', f'href="{stylesheet}?v=0.8.0"', source)
    source = re.sub(r'src="(?:\.\./)?assets/site\.js\?v=[^"]+"', f'src="{script_url}?v=0.7.0"', source)
    source = re.sub(r'href="(?:\.\./)?favicon\.svg"', f'href="{icon_url}"', source)

    jsonld_config = config["schema_home" if page == "index" else "schema_docs"]
    def update_jsonld(match: re.Match) -> str:
        try:
            data = json.loads(match.group(2))
        except json.JSONDecodeError:
            return match.group(0)
        if page == "index":
            data["description"] = jsonld_config
        else:
            data["headline"] = config["schema_headline"]
            data["description"] = jsonld_config
        data["url"] = canonical
        data["inLanguage"] = config["lang"]
        serialized = json.dumps(data, ensure_ascii=False, indent=2)
        return match.group(1) + serialized + match.group(3)
    source = re.sub(r'(<script type="application/ld\+json">\s*)(.*?)(\s*</script>)', update_jsonld, source, count=1, flags=re.S)

    source = re.sub(r'\s*<link rel="alternate" hreflang="[^"]+" href="[^"]+">', "", source)
    alternates = []
    mapping = {"en": f"{BASE_URL}/" if page == "index" else f"{BASE_URL}/docs.html"}
    for code, locale in LOCALES.items():
        mapping[locale["lang"]] = f"{BASE_URL}/{code}/" if page == "index" else f"{BASE_URL}/{code}/docs.html"
    for code, url in mapping.items():
        alternates.append(f'  <link rel="alternate" hreflang="{code}" href="{url}">')
    alternates.append(f'  <link rel="alternate" hreflang="x-default" href="{mapping["en"]}">')
    source = source.replace("</head>", "\n".join(alternates) + "\n</head>", 1)

    language_nav = render_language_nav(slug, page, config["language_label"])
    source = re.sub(r'<div class="language-nav"[^>]*>.*?</div>', lambda _: language_nav, source, count=1, flags=re.S)
    return source


def main() -> None:
    for slug, config in LOCALES.items():
        destination = ROOT / slug
        destination.mkdir(exist_ok=True)
        for page, input_name in (("index", "index.html"), ("docs", "docs.html")):
            source = (ROOT / input_name).read_text(encoding="utf-8")
            output = localize_html(source, slug, config, page)
            filename = "index.html" if page == "index" else "docs.html"
            (destination / filename).write_text(output.rstrip() + "\n", encoding="utf-8")
            print(f"Wrote {destination / filename}")

    for page, filename in (("index", "index.html"), ("docs", "docs.html")):
        path = ROOT / filename
        source = path.read_text(encoding="utf-8")
        source = re.sub(r'\s*<link rel="alternate" hreflang="[^"]+" href="[^"]+">', "", source)
        mapping = {"en": f"{BASE_URL}/" if page == "index" else f"{BASE_URL}/docs.html"}
        for slug, locale in LOCALES.items():
            mapping[locale["lang"]] = f"{BASE_URL}/{slug}/" if page == "index" else f"{BASE_URL}/{slug}/docs.html"
        alternates = [f'  <link rel="alternate" hreflang="{code}" href="{url}">' for code, url in mapping.items()]
        alternates.append(f'  <link rel="alternate" hreflang="x-default" href="{mapping["en"]}">')
        source = source.replace("</head>", "\n".join(alternates) + "\n</head>", 1)
        source = re.sub(r'<div class="language-nav"[^>]*>.*?</div>', lambda _: render_language_nav("en", page, "Language"), source, count=1, flags=re.S)
        source = re.sub(r'assets/site\.css\?v=[^"\']+', 'assets/site.css?v=0.8.0', source)
        path.write_text(source, encoding="utf-8")
        print(f"Updated English alternates in {path}")

    urls = [f"{BASE_URL}/", f"{BASE_URL}/docs.html"]
    for slug in LOCALES:
        urls.extend((f"{BASE_URL}/{slug}/", f"{BASE_URL}/{slug}/docs.html"))
    rows = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    ]
    for url in urls:
        rows.extend(("  <url>", f"    <loc>{url}</loc>", f"    <lastmod>{date.today().isoformat()}</lastmod>", "  </url>"))
    rows.append("</urlset>")
    (ROOT / "sitemap.xml").write_text("\n".join(rows) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
